ALTER TABLE orders ADD INDEX idx_created (created_at);

-- 失效：对列套了 DATE()
EXPLAIN SELECT id FROM orders WHERE DATE(created_at) = '2026-03-01';

-- 生效：改成区间
EXPLAIN SELECT id FROM orders
WHERE created_at >= '2026-03-01 00:00:00'
  AND created_at <  '2026-03-02 00:00:00';

ALTER TABLE users ADD INDEX idx_phone (phone);

-- 失效：phone 是字符串列，却拿数字比
EXPLAIN SELECT id FROM users WHERE phone = 13800000001;

-- 生效：值加引号
EXPLAIN SELECT id FROM users WHERE phone = '13800000001';

-- 生效：前缀匹配
EXPLAIN SELECT id FROM users WHERE phone LIKE '138%';
